{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01N2hwMBf2hmjrjZ3PdDawUw","type":"tool_result","content":[{"type":"text","text":"<repo>github.com/openmrs/openmrs-esm-patient-chart</repo>\n<path>packages/esm-patient-tests-app/src/test-results/filter/filter-context.tsx</path>\n<url>undefined</url>\n<content>\n1: import React, { createContext, useReducer, useEffect, useMemo } from 'react';\n2: import { formatDate, formatTime, parseDate } from '@openmrs/esm-framework';\n3: import { type MappedObservation, type TestResult, type GroupedObservation, type Observation } from '../../types';\n4: import {\n5:   ReducerActionType,\n6:   type FilterContextProps,\n7:   type ObservationData,\n8:   type ReducerState,\n9:   type TimelineData,\n10:   type TreeNode,\n11: } from './filter-types';\n12: import reducer, { mergeObsMultisetMax } from './filter-reducer';\n13: \n14: function parseTime(sortedTimes: Array<string>) {\n15:   const yearColumns: Array<{ year: string; size: number }> = [],\n16:     dayColumns: Array<{ year: string; day: string; size: number }> = [],\n17:     timeColumns: string[] = [];\n18: \n19:   sortedTimes.forEach((datetime) => {\n20:     const parsedDate = parseDate(datetime);\n21:     const year = parsedDate.getFullYear().toString();\n22:     const date = formatDate(parsedDate, { mode: 'wide', year: false, time: false });\n23:     const time = formatTime(parsedDate);\n24: \n25:     const yearColumn = yearColumns.find(({ year: innerYear }) => year === innerYear);\n26:     if (yearColumn) yearColumn.size++;\n27:     else yearColumns.push({ year, size: 1 });\n28: \n29:     const dayColumn = dayColumns.find(({ year: innerYear, day: innerDay }) => date === innerDay && year === innerYear);\n30:     if (dayColumn) dayColumn.size++;\n31:     else dayColumns.push({ day: date, year, size: 1 });\n32: \n33:     timeColumns.push(time);\n34:   });\n35: \n36:   return { yearColumns, dayColumns, timeColumns, sortedTimes };\n37: }\n38: \n39: // Derive t